def preorder(root):
    if root is None:
        return []
    return [root.value] + preorder(root.left) + preorder(root.right)

root = Node(1, Node(2), Node(3))
print(preorder(root))  # [1, 2, 3]

from collections import deque

class Node:
    def __init__(self, value, left=None, right=None):
        self.value, self.left, self.right = value, left, right

def level_order(root):
    if root is None:
        return []
    queue = deque([root])
    result = []
    while queue:
        node = queue.popleft()
        result.append(node.value)
        if node.left: queue.append(node.left)
        if node.right: queue.append(node.right)
    return result

print(level_order(Node(1, Node(2), Node(3))))  # [1, 2, 3]

def graph_dfs(graph, start):
    visited = set()
    order = []
    def visit(node):
        if node in visited:
            return
        visited.add(node)
        order.append(node)
        for neighbor in graph.get(node, []):
            visit(neighbor)
    visit(start)
    return order

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': [], 'D': []}
print(graph_dfs(graph, 'A'))  # ['A', 'B', 'D', 'C']

from collections import deque

def shortest_path(graph, start, goal):
    queue = deque([(start, [start])])
    visited = {start}
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return []

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
print(shortest_path(graph, 'A', 'D'))  # ['A', 'B', 'D']

def climb_stairs(n):
    if n < 0:
        raise ValueError('n must be nonnegative')
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a

print(climb_stairs(4))  # 5

def min_coins(coins, amount):
    if amount < 0 or any(c <= 0 for c in coins):
        raise ValueError('amount >= 0 and positive coins required')
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for total in range(1, amount + 1):
        for coin in coins:
            if coin <= total:
                dp[total] = min(dp[total], dp[total - coin] + 1)
    return -1 if dp[amount] > amount else dp[amount]

print(min_coins([1, 3, 4], 6))  # 2

import heapq

def k_largest(nums, k):
    if k < 0:
        raise ValueError('k must be nonnegative')
    return heapq.nlargest(k, nums)

print(k_largest([5, 1, 9, 3], 2))  # [9, 5]
